import{_ as e,K as a,L as r,a5 as n,W as l,F as t}from"./framework-edebdfe1.js";const o={},s=l('<h1 id="安全漏洞" tabindex="-1"><a class="header-anchor" href="#安全漏洞" aria-hidden="true">#</a> 安全漏洞</h1><h2 id="一、数据层-data-level" tabindex="-1"><a class="header-anchor" href="#一、数据层-data-level" aria-hidden="true">#</a> 一、数据层（Data-Level）</h2><h3 id="_1-训练数据投毒-data-poisoning" tabindex="-1"><a class="header-anchor" href="#_1-训练数据投毒-data-poisoning" aria-hidden="true">#</a> 1. 训练数据投毒（Data Poisoning）</h3><ul><li><strong>方式</strong>： <ul><li>注入恶意样本</li><li>标签污染（Label Flipping）</li><li>隐蔽后门样本（Backdoor Trigger）</li></ul></li><li><strong>影响</strong>： <ul><li>模型在特定输入下行为失控</li><li>定向误判 / 绕过安全策略</li></ul></li><li><strong>典型场景</strong>： <ul><li>开源数据集</li><li>Web 爬取语料</li><li>用户反馈自动回流训练（RLHF）</li></ul></li></ul><h3 id="_2-数据隐私泄露" tabindex="-1"><a class="header-anchor" href="#_2-数据隐私泄露" aria-hidden="true">#</a> 2. 数据隐私泄露</h3><ul><li><strong>漏洞点</strong>： <ul><li>训练数据含敏感信息</li><li>过拟合导致可反推原始数据</li></ul></li><li><strong>攻击方式</strong>： <ul><li>Membership Inference Attack（成员推断攻击）</li><li>Model Inversion Attack（模型反演）</li><li>数据再识别 / 提取</li></ul></li></ul>',6),h=l('<hr><h2 id="二、模型层-model-level" tabindex="-1"><a class="header-anchor" href="#二、模型层-model-level" aria-hidden="true">#</a> 二、模型层（Model-Level）</h2><h3 id="_1-对抗性攻击-adversarial-attacks" tabindex="-1"><a class="header-anchor" href="#_1-对抗性攻击-adversarial-attacks" aria-hidden="true">#</a> 1. 对抗性攻击（Adversarial Attacks）</h3><ul><li><strong>方式</strong>： <ul><li>微小扰动输入导致输出错误</li><li>物理世界攻击（贴纸、光照干扰）</li></ul></li><li><strong>影响</strong>： <ul><li>分类错误</li><li>自动驾驶 / 安防系统误判</li></ul></li></ul><h3 id="_2-模型中毒-model-poisoning-backdoor" tabindex="-1"><a class="header-anchor" href="#_2-模型中毒-model-poisoning-backdoor" aria-hidden="true">#</a> 2. 模型中毒（Model Poisoning / Backdoor）</h3><ul><li><strong>方式</strong>： <ul><li>在模型训练或微调阶段注入后门权重</li></ul></li><li><strong>影响</strong>： <ul><li>模型在触发条件下执行恶意行为</li><li>无需访问训练数据即可触发</li></ul></li></ul><h3 id="_3-模型窃取-model-stealing" tabindex="-1"><a class="header-anchor" href="#_3-模型窃取-model-stealing" aria-hidden="true">#</a> 3. 模型窃取（Model Stealing）</h3><ul><li><strong>方式</strong>： <ul><li>通过 API 查询和输出推测模型参数或行为</li></ul></li><li><strong>影响</strong>： <ul><li>商业模型被复制或重构</li><li>可用于后续对抗攻击</li></ul></li></ul><hr><h2 id="三、推理层-inference-level" tabindex="-1"><a class="header-anchor" href="#三、推理层-inference-level" aria-hidden="true">#</a> 三、推理层（Inference-Level）</h2><h3 id="_1-prompt-injection-指令注入" tabindex="-1"><a class="header-anchor" href="#_1-prompt-injection-指令注入" aria-hidden="true">#</a> 1. Prompt Injection / 指令注入</h3><ul><li><strong>方式</strong>： <ul><li>构造恶意输入诱导模型执行未授权操作</li><li>如泄露内部信息、执行计算任务</li></ul></li><li><strong>影响</strong>： <ul><li>数据泄露</li><li>AI 误操作</li></ul></li></ul><h3 id="_2-输出滥用" tabindex="-1"><a class="header-anchor" href="#_2-输出滥用" aria-hidden="true">#</a> 2. 输出滥用</h3><ul><li><strong>方式</strong>： <ul><li>利用模型生成有害内容（诈骗、仇恨言论、深度伪造）</li></ul></li><li><strong>影响</strong>： <ul><li>法律风险</li><li>品牌或平台安全威胁</li></ul></li></ul><hr><h2 id="四、智能体层-agent-level" tabindex="-1"><a class="header-anchor" href="#四、智能体层-agent-level" aria-hidden="true">#</a> 四、智能体层（Agent-Level）</h2><h3 id="_1-智能体滥用" tabindex="-1"><a class="header-anchor" href="#_1-智能体滥用" aria-hidden="true">#</a> 1. 智能体滥用</h3><ul><li><strong>方式</strong>： <ul><li>利用自主决策能力完成恶意任务</li><li>多智能体协作进行自动化攻击</li></ul></li><li><strong>影响</strong>： <ul><li>分布式网络攻击</li><li>社交媒体操纵</li><li>自动化漏洞扫描与渗透</li></ul></li></ul><h3 id="_2-智能体被操控" tabindex="-1"><a class="header-anchor" href="#_2-智能体被操控" aria-hidden="true">#</a> 2. 智能体被操控</h3><ul><li><strong>方式</strong>： <ul><li>对智能体策略或奖励函数进行干扰</li></ul></li><li><strong>影响</strong>： <ul><li>完成攻击者预设的目标</li><li>系统行为不可控</li></ul></li></ul><hr><h2 id="五、系统集成层-system-level" tabindex="-1"><a class="header-anchor" href="#五、系统集成层-system-level" aria-hidden="true">#</a> 五、系统集成层（System-Level）</h2><h3 id="_1-api-接口安全漏洞" tabindex="-1"><a class="header-anchor" href="#_1-api-接口安全漏洞" aria-hidden="true">#</a> 1. API / 接口安全漏洞</h3><ul><li><strong>方式</strong>： <ul><li>不安全的模型部署接口</li><li>身份验证缺失或错误</li></ul></li><li><strong>影响</strong>： <ul><li>非授权访问</li><li>数据泄露</li><li>模型被远程利用</li></ul></li></ul><h3 id="_2-供应链攻击" tabindex="-1"><a class="header-anchor" href="#_2-供应链攻击" aria-hidden="true">#</a> 2. 供应链攻击</h3><ul><li><strong>方式</strong>： <ul><li>利用开源库、预训练模型或微服务组件植入恶意代码</li></ul></li><li><strong>影响</strong>： <ul><li>企业级系统被入侵</li><li>后门攻击和长期潜伏威胁</li></ul></li></ul><h3 id="_3-日志与监控缺失" tabindex="-1"><a class="header-anchor" href="#_3-日志与监控缺失" aria-hidden="true">#</a> 3. 日志与监控缺失</h3><ul><li><strong>方式</strong>： <ul><li>缺乏对 AI 系统行为的监控</li></ul></li><li><strong>影响</strong>： <ul><li>攻击难以追踪</li><li>安全事件响应延迟</li></ul></li></ul><hr><h2 id="六、总结" tabindex="-1"><a class="header-anchor" href="#六、总结" aria-hidden="true">#</a> 六、总结</h2><ul><li>AI 安全漏洞贯穿整个生命周期：<strong>数据 → 模型 → 推理 → 智能体 → 系统集成</strong></li><li>核心威胁类型： <ul><li><strong>投毒、后门、对抗攻击、提示注入、模型窃取、输出滥用</strong></li></ul></li><li>防护建议： <ul><li>安全数据治理</li><li>模型防护（对抗训练、访问控制）</li><li>推理/智能体行为监控</li><li>API 安全与供应链安全</li></ul></li></ul>',31);function d(u,c){const i=t("DocsAD");return a(),r("div",null,[s,n(i),h])}const _=e(o,[["render",d],["__file","vul.html.vue"]]);export{_ as default};
